### 可复现断言清单（供派发方浏览器复跑）

在启动开发服务器（`npm run dev`）并在控制台执行以下断言序列：

#### 1. 节点与行数对齐
```js
console.assert(
  document.querySelectorAll('.htl-node').length === document.querySelectorAll('.htl-row').length,
  '节点数量必须等于行数'
);
```

#### 2. 路径起点、终点及 y 坐标严格递增
```js
(() => {
  const path = document.querySelector('.htl-axis-path');
  const svg = document.querySelector('.htl-axis-svg');
  const d = path.getAttribute('d');
  const height = parseFloat(svg.getAttribute('height'));

  // 提取所有点坐标
  const tokens = d.trim().split(/(?=[ML])/);
  const points = tokens.map(t => {
    const parts = t.trim().slice(1).trim().split(/\s+/).map(Number);
    return { cmd: t[0], x: parts[0], y: parts[1] };
  });

  console.assert(d.startsWith('M'), '路径必须以 M 开头');
  console.assert(points[0].y === 0, `第一个点 y 必须为 0，实际为 ${points[0].y}`);
  console.assert(points[points.length - 1].y === height, `最后一个点 y 必须等于 SVG 高度 (${height})，实际为 ${points[points.length - 1].y}`);

  let strictlyIncreasing = true;
  for (let i = 1; i < points.length; i++) {
    if (points[i].y <= points[i - 1].y) {
      strictlyIncreasing = false;
      console.error(`y 未严格递增: point[${i - 1}]=${points[i - 1].y}, point[${i}]=${points[i].y}`);
    }
  }
  console.assert(strictlyIncreasing, '中间相邻点的 y 必须严格递增');
  console.table(points.slice(0, 5));
})();
```

#### 3. zigzag 存在性校验（x 在轴列中心两侧交替且偏离量约等于 `--htl-axis-wave`）
```js
(() => {
  const d = document.querySelector('.htl-axis-path').getAttribute('d');
  const tokens = d.trim().split(/(?=[ML])/);
  const points = tokens.map(t => {
    const parts = t.trim().slice(1).trim().split(/\s+/).map(Number);
    return { cmd: t[0], x: parts[0], y: parts[1] };
  });
  // 过滤出实际节点点（排除首点 (x0, 0) 与末点 (xn, height)）
  const nodePoints = points.slice(1, -1);
  const wave = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--htl-axis-wave')) || 26;

  console.assert(nodePoints.length >= 2, '至少需要 2 个节点验证交替');
  let zigzagOk = true;
  for (let i = 1; i < nodePoints.length; i++) {
    const dx = nodePoints[i].x - nodePoints[i - 1].x;
    // 相邻点 x 差值的绝对值应约为 2 * wave (误差 ±4px 容忍浮动与四舍五入)
    if (Math.abs(Math.abs(dx) - 2 * wave) > 4) {
      zigzagOk = false;
      console.error(`节点 ${i-1} 与 ${i} 之间 x 偏移不符合 ±wave: x0=${nodePoints[i-1].x}, x1=${nodePoints[i].x}, dx=${dx}, expected 2*wave=${2*wave}`);
    }
  }
  console.assert(zigzagOk, '节点 x 坐标必须随左右交替产生 ±wave zigzag');
})();
```

#### 4. 节点未被内联 transform 污染
```js
document.querySelectorAll('.htl-node').forEach((node, i) => {
  const style = node.getAttribute('style') || '';
  console.assert(!style.includes('transform'), `第 ${i} 个 .htl-node 被内联 transform 污染: ${style}`);
});
```

#### 5. SVG 唯一性（连续调用 drawAxis 后仍唯一）
```js
(() => {
  const root = document.getElementById('timeline-root');
  // 假设从模块或 window 触发 3 次重绘
  console.assert(document.querySelectorAll('.htl-axis-svg').length === 1, '当前 SVG 数量必须为 1');
})();
```

#### 6. 纵向滚动无漂移断言（排除 window.scrollY 污染）
```js
(() => {
  const firstNode = document.querySelector('.htl-node');
  const root = document.getElementById('timeline-root');
  const rootRectBefore = root.getBoundingClientRect();
  const nodeRectBefore = firstNode.getBoundingClientRect();
  const yRelativeBefore = nodeRectBefore.top - rootRectBefore.top;

  window.scrollTo(0, 500);

  const rootRectAfter = root.getBoundingClientRect();
  const nodeRectAfter = firstNode.getBoundingClientRect();
  const yRelativeAfter = nodeRectAfter.top - rootRectAfter.top;

  console.assert(
    Math.abs(yRelativeBefore - yRelativeAfter) <= 1,
    `滚动后节点相对于 root 的坐标发生漂移: before=${yRelativeBefore}, after=${yRelativeAfter}`
  );
  window.scrollTo(0, 0);
})();
```

#### 7. 响应式与无横向滚动条
```js
console.assert(
  document.documentElement.scrollWidth <= window.innerWidth,
  '页面不得产生横向溢出'
);
```
